practice.solution:
package main

import "fmt"

func main() {
	prices := []int{20, 35, 50}

	for _, p := range prices {
		p -= 5 // changes only the copy
	}
	fmt.Println("Through p:", prices)

	for i := range prices {
		prices[i] -= 5
	}
	fmt.Println("Through prices[i]:", prices)
}
